%%\ Low-Light Image Enhancement with Pretrained "Learning to See in the Dark" CNN
clear; clc; close all;
rng(42); % Reproducible synthetic noise

%%\ 1) Download pretrained network (only once)
dataDir = fullfile(tempdir, "Sony2025");
if ~exist(dataDir, "dir")
    mkdir(dataDir);
end

modelFile = fullfile(dataDir, "trainedLowLightCameraPipelineNet.mat");
if ~isfile(modelFile) %[output:group:0fb6dcf6]
    fprintf("Downloading pretrained low-light model...\n"); %[output:6a58f739]
    modelURL = "https://ssd.mathworks.com/supportfiles/" + ...
        "vision/data/trainedLowLightCameraPipelineDlnetwork.zip";
    zipFile  = fullfile(dataDir, "trainedLowLightCameraPipelineDlnetwork.zip");
    websave(zipFile, modelURL);
    unzip(zipFile, dataDir);
    fprintf("Download complete. Model saved in:\n%s\n", dataDir); %[output:2edfa0c4]
end %[output:group:0fb6dcf6]

%%\ 2) Load pretrained network
load(modelFile, "netTrained");

%%\ 3) Read your own dark image (auto-detects my.jpg or Example_03.png)
if isfile("my.jpg")
    inputFile = "my.jpg";
elseif isfile("Example_03.png")
    inputFile = "Example_03.png";
else
    inputFile = "peppers.png";
end

I_raw = imread(inputFile);

% Ensure 3-channel RGB (handles RGBA or grayscale inputs safely)
if size(I_raw, 3) == 4
    I_raw = I_raw(:, :, 1:3);
elseif size(I_raw, 3) == 1
    I_raw = repmat(I_raw, 1, 1, 3);
end

I = im2single(imresize(I_raw, [512 512]));
fprintf("Loaded input image: %s (resized to 512x512)\n", inputFile); %[output:28eb7ce4]

%%\ 4) Simulate low-light + noise (Baseline vs. Improved Parameters)
% Baseline parameters from starter code
darkFactor_base = 0.03;
I_dark_base     = imnoise(I * darkFactor_base, "gaussian", 0, 0.002);

% Improvement Part A: Tune darkFactor (0.03 -> 0.15) and noise variance (0.002 -> 0.0005)
% Because Example_03.png / my.jpg is already a dark image, 0.03 crushes shadow detail
darkFactor_imp  = 0.15;
I_dark_imp      = imnoise(I * darkFactor_imp, "gaussian", 0, 0.0005);

%%\ 5–8) Helper inference function & network execution
out_baseline = runSIDNetwork(netTrained, I_dark_base);
out_raw_imp  = runSIDNetwork(netTrained, I_dark_imp);

% Improvement Part B: Post-processing with contrast stretching & sharpening
% Removes the slight gray haze from CNN output and restores crisp edge detail
out_stretched = imadjust(out_raw_imp, stretchlim(out_raw_imp, [0.01 0.99]), []);
out_improved  = imsharpen(out_stretched, "Radius", 1.2, "Amount", 0.6);

% Save standalone enhanced result and 4-panel comparison for GitHub
imwrite(out_improved, "enhanced_result.png");

fig = figure("Name", "Low-Light Enhancement Comparison"); %[output:2f55f664]
tiledlayout(2, 2, "TileSpacing", "compact", "Padding", "compact"); %[output:2f55f664]

nexttile; imshow(I);            title(sprintf("1. Input (%s)", inputFile), "Interpreter", "none"); %[output:2f55f664]
nexttile; imshow(I_dark_imp);   title(sprintf("2. Low-Light + Noise (factor=%.2f)", darkFactor_imp)); %[output:2f55f664]
nexttile; imshow(out_baseline); title("3. Baseline CNN (factor=0.03)"); %[output:2f55f664]
nexttile; imshow(out_improved); title("4. Improved CNN + imadjust + imsharpen"); %[output:2f55f664]

saveas(fig, "comparison_result.png"); %[output:2f55f664]
fprintf("Saved 'enhanced_result.png' and 'comparison_result.png' in:\n%s\n", pwd); %[output:2cb5094f]

%%\ Local Function: Run Pretrained SID Network on Low-Light RGB Image
function outRGB = runSIDNetwork(net, imgLowLight)
I_gray  = rgb2gray(imgLowLight);         % H x W
rawFake = repmat(I_gray, 1, 1, 4);       % H x W x 4 ("fake RAW" channels)
input   = dlarray(rawFake, "SSCB");      % Spatial, Spatial, Channels, Batch
if canUseGPU
    input = gpuArray(input);
end
pred   = predict(net, input);            % H x W x 3 x 1
pred   = gather(extractdata(pred));
pred   = squeeze(pred);
outRGB = im2uint8(pred);
end

